import { celsiusToFahrenheit } from "../converter.js";

test("converter module exports a function", () => {
  expect(typeof celsiusToFahrenheit).toBe("function");
});

import { celsiusToFahrenheit } from "../converter.js";

test("0 celsius converts to 32 fahrenheit", () => {
  expect(celsiusToFahrenheit(0)).toBe(32);
});

import { celsiusToFahrenheit } from "../converter.js";

test("100 celsius converts to 212 fahrenheit", () => {
  expect(celsiusToFahrenheit(100)).toBe(212);
});

import { celsiusToFahrenheit } from "../converter.js";

test("-40 celsius converts to -40 fahrenheit", () => {
  expect(celsiusToFahrenheit(-40)).toBe(-40);
});

import { celsiusToFahrenheit } from "../converter.js";

test("37 celsius converts to 98.6 fahrenheit", () => {
  expect(celsiusToFahrenheit(37)).toBeCloseTo(98.6, 5);
});

import { celsiusToFahrenheit } from "../converter.js";

test("converter function handles multiple inputs", () => {
  expect(celsiusToFahrenheit(0)).toBe(32);
  expect(celsiusToFahrenheit(100)).toBe(212);
  expect(celsiusToFahrenheit(-40)).toBe(-40);
});

referenceFiles./styles.css:
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 16px;
  font-family: sans-serif;
  -webkit-font-smoothing: auto;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  -webkit-tap-highlight-color: transparent;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 16px;
}

.converter {
  max-width: 420px;
  min-width: 0;
  margin: 0 auto;
  padding: 16px;
  border: 1px solid #d0d7de;
  border-radius: 8px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}

.field input {
  width: 100%;
  min-width: 0;
  padding: 8px;
  font-size: 1rem;
  border: 1px solid #c0c7ce;
  border-radius: 6px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.actions button {
  padding: 8px 16px;
  font-size: 1rem;
  border: none;
  border-radius: 6px;
  background: #2563eb;
  color: #fff;
  cursor: pointer;
}

.result-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px;
  font-size: 1.1rem;
}

#result {
  font-weight: 600;
}

referenceFiles./index.js:
import "./styles.css";
import { celsiusToFahrenheit } from "./converter.js";

const input = document.getElementById("celsius-input");
const convertButton = document.getElementById("convert-button");
const result = document.getElementById("result");

convertButton.addEventListener("click", () => {
  const celsius = Number(input.value);
  const fahrenheit = celsiusToFahrenheit(celsius);
  result.textContent = String(fahrenheit);
});

referenceFiles./converter.js:
export function celsiusToFahrenheit(celsius) {
  return (celsius * 9) / 5 + 32;
}

export default celsiusToFahrenheit;

